package run.ikaros.music; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v2/music/playback") public class MusicPlaybackController{private final MusicPlaybackService service;public MusicPlaybackController(MusicPlaybackService s){service=s;}@PostMapping("/tracks/{trackId}/sessions")public Mono<MusicPlaybackSessionView> start(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID trackId,@Valid@RequestBody StartMusicPlaybackRequest r){return service.start(o,trackId,r);}@PatchMapping("/sessions/{sessionId}")public Mono<MusicPlaybackSessionView> update(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID sessionId,@Valid@RequestBody UpdateMusicPlaybackRequest r){return service.update(o,sessionId,r);}@PostMapping("/sessions/{sessionId}/actions/end")public Mono<MusicPlaybackSessionView> end(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID sessionId,@Valid@RequestBody EndMusicPlaybackRequest r){return service.end(o,sessionId,r);}@GetMapping("/history")public Flux<MusicPlaybackHistoryView> history(@RequestHeader("X-Ikaros-Actor-Id")UUID o){return service.history(o);}}
